import{_ as t,o as c,c as o,a3 as i}from"./chunks/framework.CRbjHCyB.js";const g=JSON.parse('{"title":"索引","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"索引 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/cli/"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/cli/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/"}]]},"headers":[],"relativePath":"zh/clice/cli/index.md","filePath":"zh/clice/cli/index.md","lastUpdated":1789443039000}'),l={name:"zh/clice/cli/index.md"};function a(r,e,n,d,s,h){return c(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="索引" tabindex="-1">索引 <a class="header-anchor" href="#索引" aria-label="Permalink to &quot;索引&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><code>clice index</code> 预先为工作区构建持久化符号索引，让编辑器会话热启动，而不是在你工作时才在后台建立索引。它用 worker 池运行与服务器相同的索引流程，两者共用 <code>cache_dir</code> 下的索引，每个构建配置各一份。</p><p><strong>用法</strong>：<code>clice index [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] [--workers &lt;n&gt;]</code></p><p>索引构建可在中断后继续：按 Ctrl-C 中断会保存当前进度，下次执行时会从中断处继续。每五分钟也会保存一次进度，因此崩溃最多只会损失五分钟的工作。运行期间，无论日志级别如何，每十秒都会向 stderr 输出一行进度；最终在 stdout 输出的摘要会统计已建立索引的翻译单元数、生成的文件分片数和符号数，列出所有索引构建失败的翻译单元，并给出会话日志目录。索引完整时退出码为 0，部分翻译单元索引失败或部分索引无法持久化时为 1，中断时为 130。</p><h2 id="查看索引" tabindex="-1">查看索引 <a class="header-anchor" href="#查看索引" aria-label="Permalink to &quot;查看索引&quot;">​</a></h2><p>同一条命令也能读取已持久化的索引，而不改动它。所有查看模式都输出纯文本行，便于在终端查看或交给 <code>grep</code> 处理；即使编辑器会话正打开着索引，这些模式也能正常工作。</p><ul><li><code>clice index --stats [--top &lt;n&gt;]</code> 输出索引内容的统计信息：翻译单元和文件分片、分片各列及全局符号表的字节占用明细、符号按引用文件数和名称长度的分布、文件分片按变体数量的分布，以及最大的分片。<code>--variants</code> 会为每个文件分片追加一行以制表符分隔的记录，其中包含该分片的变体数量，便于比较两次运行的结果。</li><li><code>clice index --show-symbol &lt;name&gt;</code> 输出索引中记录的符号信息：种类、名称和标志，拼出其限定名的父级链，规范声明所在的文件，以及各文件中定义、声明和引用的数量。名称按显示形式（<code>Box&lt;int&gt;</code>）或限定形式（<code>ns::Box&lt;int&gt;</code>）匹配；<code>#&lt;hash&gt;</code> 按符号标识指定符号，文件局部符号就是通过这种方式访问的。</li><li><code>clice index --show-file &lt;path&gt;</code> 输出文件已持久化的数据行：构建这些行所依据的内容版本、每个变体及贡献它的翻译单元，按关系类型统计的行数，以及身份只存在于该文件中的文件局部符号。</li><li><code>clice index --show-tu &lt;path&gt;</code> 输出翻译单元的清单：索引时间、它为哪些文件贡献了数据行，以及它的包含树。</li></ul>',8)])])}const m=t(l,[["render",a]]);export{g as __pageData,m as default};
